$N = (int)trim(fgets(STDIN));

// The number of segments is C(N+1, 2) = (N+1)*N/2
// We need to find the minimum number of layers such that no two segments in the same layer overlap.
// Two segments [a,b] and [c,d] overlap if they share an interior point, i.e., max(a,c) < min(b,d).
// They can touch at endpoints.

// This is equivalent to finding the maximum depth (maximum number of segments covering any single point in the interior).
// Actually, the minimum number of layers equals the maximum number of segments that cover any single point (considering open intervals or the interior).

// Let's think about it differently. A segment from i to j (where i < j) covers all integer points i+1, i+2, ..., j-1 in its interior.
// Two segments overlap if their interiors intersect.
// So we need to color the segments such that no two segments with overlapping interiors have the same color.
// This is equivalent to finding the maximum number of segments whose interiors all contain a common point.

// For a point x (where 1 <= x <= N-1), the segments that cover x in their interior are those with i < x < j, i.e., i <= x-1 and j >= x+1.
// The number of such segments is x * (N - x).

// So the answer is the maximum value of x * (N - x) for x = 1, 2, ..., N-1.

function solve($N) {
    if ($N <= 1) {
        return 0;
    }
    $max = 0;
    for ($x = 1; $x <= $N - 1; $x++) {
        $count = $x * ($N - $x);
        if ($count > $max) {
            $max = $count;
        }
    }
    return $max;
}

echo solve($N) . "\n";
?>
